void mainImage(out vec4 O, vec2 u) {

    float r =.2, t=iTime, H=iResolution.y, i=r;
    vec2  U =  u/H, f,
          P = .5+.5* cos(vec2(t,t*.7+11.));     // disc location
    O *= 0.;

    for ( O.b = .25 ; 
          ++i < 8. ;                            // recursive loop
          min(f.x,f.y) < 3.*r/H    
            ? O--                               // square border
    	    : length(P-1.) - r < 1.4            // in cell: if close to disc,
        	    ? f = 2.*step(1.,U),            // 2x2 subdivision
        	      U += U - f,
        	      P += P - f,  r += r,
        	      O += .13                      // whiter with depth
                : O 
        )
        f = min( U, 2.-U );

    length(P-U) < r ? O.gb-- : U;               // draw disc
}
